// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getValue, getResponseValue, uniqueSuffix, checkSchema } from '@skyramp/skyramp';
import { getCoupon } from './skyrampUtils';

// URL for test requests
const URL_localhost = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:3000");

// Stays local: the shared createCoupon helper always sends an expirationDate key, and this
// scenario is specifically about a body that OMITS the field entirely.
async function createCouponWithoutExpirationDate(
    client: SkyrampClient,
    headers: Record<string, string>,
    code: string,
    expectedStatus = 201
) {
    // Request Body
    const couponsPostRequestBody: string = `{
        "code": "TESTBOT-NOEXP-A1",
        "discountPercent": 0
    }`;

    // Execute Request
    const couponsPostResponse = await client.sendRequest({
        url: URL_localhost,
        path: "/api/v1/coupons",
        method: "POST",
        body: couponsPostRequestBody,
        headers: headers,
        dataOverride: {"code": code}
    });

    // Generated Assertions
    expect(couponsPostResponse.statusCode, 'status code').toBe(expectedStatus);

    return couponsPostResponse;
}

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Definition of authentication header
    const headers: Record<string, string> = {};
    if (process.env.SKYRAMP_TEST_TOKEN && process.env.SKYRAMP_TEST_TOKEN != "") {
        headers["Authorization"] = "Bearer " + process.env.SKYRAMP_TEST_TOKEN;
    }

    const couponCode = uniqueSuffix("TESTBOT-NOEXP-A1");

    const couponsPostResponse = await createCouponWithoutExpirationDate(client, headers, couponCode, 201);

    expect(getResponseValue(couponsPostResponse, "response.code"), 'code').toBe(couponCode);
    expect(getResponseValue(couponsPostResponse, "response.discountPercent"), 'discountPercent').toBe(0);
    expect(getResponseValue(couponsPostResponse, "response.expirationDate"), 'expirationDate').toBeNull();
    expect(checkSchema(couponsPostResponse, '{"response": {"expirationDate": null}}'), 'expirationDate is present and null').toBe(true);
    expect(Number(getResponseValue(couponsPostResponse, "response.id")), 'id').toBeGreaterThan(0);
    expect(String(getResponseValue(couponsPostResponse, "response.createdAt")), 'createdAt').toMatch(/^\d{4}-\d{2}-\d{2}T/);

    const couponsCouponsGetResponse = await getCoupon(
        client,
        headers,
        getResponseValue(couponsPostResponse, "response.id"),
        200
    );

    expect(getResponseValue(couponsCouponsGetResponse, "response.id"), 'id').toBe(getResponseValue(couponsPostResponse, "response.id"));
    expect(getResponseValue(couponsCouponsGetResponse, "response.code"), 'code').toBe(couponCode);
    expect(getResponseValue(couponsCouponsGetResponse, "response.discountPercent"), 'discountPercent').toBe(0);
    expect(getResponseValue(couponsCouponsGetResponse, "response.expirationDate"), 'expirationDate').toBeNull();
    expect(checkSchema(couponsCouponsGetResponse, '{"response": {"expirationDate": null}}'), 'expirationDate is present and null on read-back').toBe(true);
});
